+        dataView.refreshAll();
+        updateUrl(name, statuses);
+    }
+
+    private void updateUrl(String name, List<CustomerStatus> statuses) {
+        Map<String, List<String>> params = new LinkedHashMap<>();
+        if (!name.isEmpty()) {
+            params.put("name", List.of(name));
+        }
+        if (!statuses.isEmpty()) {
+            params.put("status", List.of(statuses.stream().map(Enum::name).collect(Collectors.joining(","))));
+        }
+
+        Location location = new Location(List.of(""), new QueryParameters(params));
+        UI.getCurrent().getPage().getHistory().replaceState(null, location);
+    }
+
+    private void updateSummary(int matching) {
+        summary.setText("Showing " + matching + " of " + totalCount);
+    }
+
+    private static List<CustomerStatus> parseStatuses(String raw) {
+        return Arrays.stream(raw.split(","))
+                .map(String::trim)
+                .filter(s -> !s.isEmpty())
+                .map(CustomerStatus::valueOf)
+                .toList();
     }

