+
+        nameField.setValue("");
+        page.waitForURL(url -> !url.contains("name="));
+
+        GridElement grid = GridElement.get(page);
+        grid.waitForGridToStopLoading();
+        grid.assertRowCount(500);
+    }
+
+    @Test
+    void openingAUrlWithQueryParametersAppliesAndDisplaysTheFilter() {
+        page.navigate(getUrl() + "?name=vir&status=ACTIVE,CLOSED");
+
+        TextFieldElement nameField = new TextFieldElement(page.locator(NAME_FIELD_SELECTOR));
+        nameField.assertValue("vir");
+
+        MultiSelectComboBoxElement statusField = MultiSelectComboBoxElement.getByLabel(page, "Status");
+        statusField.assertSelectedItems("ACTIVE", "CLOSED");
+
+        GridElement grid = GridElement.get(page);
+        grid.waitForGridToStopLoading();
+        grid.assertRowCount(10);
+
+        assertEquals("Showing 10 of 500", page.locator("text=Showing").textContent());
+    }
+}
